function updateDistSim() {
    const a = parseInt(document.getElementById('slider-a').value, 10);
    const b = parseInt(document.getElementById('slider-b').value, 10);
    const c = parseInt(document.getElementById('slider-c').value, 10);

    document.getElementById('badge-a').innerText = 'a = ' + a;
    document.getElementById('badge-b').innerText = 'b = ' + b;
    document.getElementById('badge-c').innerText = 'c = ' + c;

    const area1 = a * b;
    const area2 = a * c;
    const total = area1 + area2;

    document.getElementById('factored-readout').innerText = total;
    document.getElementById('factored-calc').innerText = `${a} × (${b} + ${c}) = ${total}`;

    document.getElementById('expanded-readout').innerText = total;
    document.getElementById('expanded-calc').innerText = `${area1} + ${area2} = ${total}`;

    document.getElementById('dist-rect-1').style.flex = b;
    document.getElementById('dist-rect-2').style.flex = c;
    document.getElementById('rect-1-val').innerText = area1;
    document.getElementById('rect-2-val').innerText = area2;

    document.getElementById('dist-summary-pill').innerHTML = 
        `<i class="fas fa-check-circle" style="color:#10b981;"></i> Area Equivalence: $${a}(${b} + ${c}) = ${a}(${b}) + ${a}(${c}) = ${total}$`;

    if (window.MathJax && window.MathJax.typesetPromise) {
        window.MathJax.typesetPromise([document.getElementById('dist-summary-pill')]);
    }
}

function setDistSim(a, b, c) {
    document.getElementById('slider-a').value = a;
    document.getElementById('slider-b').value = b;
    document.getElementById('slider-c').value = c;
    updateDistSim();
}

document.addEventListener('DOMContentLoaded', () => {
    updateDistSim();
});
